describe('Profile Update Confirmation Message', () => {
  beforeEach(() => {
    cy.visit('/profile');
  });

  it('should display confirmation message after successful profile update', () => {
    // Intercept the profile update API call
    cy.intercept('PUT', '/api/profile').as('updateProfile');

    // Fill in new profile details
    cy.get('[data-testid="firstName-input"]').type('John');
    cy.get('[data-testid="lastName-input"]').type('Doe');
    cy.get('[data-testid="email-input"]').type('john.doe@example.com');

    // Click the update button
    cy.get('[data-testid="update-profile-button"]').click();

    // Wait for the API call
    cy.wait('@updateProfile');

    // Verify success message is displayed
    cy.get('[data-testid="confirmation-message"]')
      .should('be.visible')
      .should('contain', 'Profile updated successfully');

    // Verify success styling
    cy.get('[data-testid="confirmation-message"]')
      .should('have.class', 'success-message');

    // Verify form is cleared or updated
    cy.get('[data-testid="firstName-input"]').should('have.value', 'John');
    cy.get('[data-testid="lastName-input"]').should('have.value', 'Doe');
  });

  it('should not display confirmation message when profile update fails', () => {
    // Intercept the profile update API call and mock a failure response
    cy.intercept('PUT', '/api/profile', {
      statusCode: 400,
      body: { error: 'Email already in use' }
    }).as('updateProfileFailed');

    // Fill in invalid profile details
    cy.get('[data-testid="firstName-input"]').type('Jane');
    cy.get('[data-testid="lastName-input"]').type('Smith');
    cy.get('[data-testid="email-input"]').type('jane@example.com');

    // Click the update button
    cy.get('[data-testid="update-profile-button"]').click();

    // Wait for the failed API call
    cy.wait('@updateProfileFailed');

    // Verify error message is displayed instead of success message
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Email already in use');

    // Verify success message is NOT displayed
    cy.get('[data-testid="confirmation-message"]')
      .should('not.exist');

    // Verify form still contains input values
    cy.get('[data-testid="firstName-input"]').should('have.value', 'Jane');
  });
});
